From 90e8a82ad2c24a1d9bcd16b25ba7073ad3ef477b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:03:36 +0100
Subject: [PATCH] daemon: optionally switch to Power Save at critical battery
 level

The critical battery level only had a final action, so the power profile
stayed the same until the battery ran out. Add an option to hold the
power-saver profile while the battery is critical and not charging.

BUG: 525875
---
 PowerDevilGlobalSettings.kcfg |  3 ++
 daemon/powerdevilcore.cpp     | 65 +++++++++++++++++++++++++++++++++++
 daemon/powerdevilcore.h       |  4 +++
 kcm/ui/GlobalConfig.qml       | 14 ++++++++
 4 files changed, 86 insertions(+)

diff --git a/PowerDevilGlobalSettings.kcfg b/PowerDevilGlobalSettings.kcfg
index f8e9f5521..26e45091c 100644
--- a/PowerDevilGlobalSettings.kcfg
+++ b/PowerDevilGlobalSettings.kcfg
@@ -30,6 +30,9 @@
         PowerDevil::GlobalDefaults::defaultBatteryCriticalAction(mParamCanSuspend, mParamCanHibernate)
       </default>
     </entry>
+    <entry name="BatteryCriticalPowerSaver" type="Bool">
+      <default>false</default>
+    </entry>
     <entry name="PeripheralBatteryLowLevel" type="Int">
       <default>10</default>
     </entry>
diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 33badced8..52b4fab92 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -361,6 +361,9 @@ void Core::loadProfile(bool force)
             m_pendingWakeupEvent = false;
         }
     } else {
+        // Applying the profile's power profile drops any profile hold, so take it again afterwards
+        releaseCriticalBatteryPowerProfileHold();
+
         // First of all, let's clean the old actions. This will also call the onProfileUnload callback
         unloadAllActiveActions();

@@ -422,6 +425,8 @@ void Core::loadProfile(bool force)
     if (m_lidController->isLidClosed() && (m_currentProfile != profileId || force)) {
         Q_EMIT m_lidController->lidClosedChanged(true);
     }
+
+    updateCriticalBatteryPowerProfileHold();
 }

 void Core::onDeviceAdded(const QString &udi)
@@ -475,6 +480,8 @@ void Core::onDeviceAdded(const QString &udi)
         // This stops the timer, so for the notification we check if it was active before that.
         cancelCriticalBatteryNotification();
     }
+
+    updateCriticalBatteryPowerProfileHold();
 }

 void Core::onDeviceRemoved(const QString &udi)
@@ -824,6 +831,64 @@ void Core::triggerCriticalBatteryAction()
     }
 }

+static void releasePowerProfileHold(uint cookie)
+{
+    QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.UPower.PowerProfiles"),
+                                                      QStringLiteral("/org/freedesktop/UPower/PowerProfiles"),
+                                                      QStringLiteral("org.freedesktop.UPower.PowerProfiles"),
+                                                      QStringLiteral("ReleaseProfile"));
+    msg << cookie;
+    QDBusConnection::systemBus().asyncCall(msg);
+}
+
+void Core::updateCriticalBatteryPowerProfileHold()
+{
+    const bool shouldHold = m_globalSettings->batteryCriticalPowerSaver() && !m_batteriesPercent.isEmpty()
+        && m_batteryController->acAdapterState() != BatteryController::Plugged && currentChargePercent() <= m_globalSettings->batteryCriticalLevel();
+
+    if (!shouldHold) {
+        releaseCriticalBatteryPowerProfileHold();
+        return;
+    }
+    if (m_criticalBatteryPowerProfileHeld) {
+        return;
+    }
+    m_criticalBatteryPowerProfileHeld = true;
+
+    QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.UPower.PowerProfiles"),
+                                                      QStringLiteral("/org/freedesktop/UPower/PowerProfiles"),
+                                                      QStringLiteral("org.freedesktop.UPower.PowerProfiles"),
+                                                      QStringLiteral("HoldProfile"));
+    msg << QStringLiteral("power-saver") << i18n("Battery level is critical") << QStringLiteral("kcm_powerdevilprofilesconfig");
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(msg), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, watcher] {
+        watcher->deleteLater();
+        QDBusPendingReply<uint> reply = *watcher;
+        if (reply.isError()) {
+            qCWarning(POWERDEVIL) << "Failed to hold the power-saver profile at critical battery level:" << reply.error().message();
+            return;
+        }
+        if (!m_criticalBatteryPowerProfileHeld) {
+            // The battery stopped being critical while waiting for the reply
+            releasePowerProfileHold(reply.value());
+            return;
+        }
+        if (m_criticalBatteryPowerProfileCookie) {
+            releasePowerProfileHold(m_criticalBatteryPowerProfileCookie);
+        }
+        m_criticalBatteryPowerProfileCookie = reply.value();
+    });
+}
+
+void Core::releaseCriticalBatteryPowerProfileHold()
+{
+    m_criticalBatteryPowerProfileHeld = false;
+    if (m_criticalBatteryPowerProfileCookie) {
+        releasePowerProfileHold(m_criticalBatteryPowerProfileCookie);
+        m_criticalBatteryPowerProfileCookie = 0;
+    }
+}
+
 void Core::cancelCriticalBatteryNotification()
 {
     m_criticalBatteryTimer->stop();
diff --git a/daemon/powerdevilcore.h b/daemon/powerdevilcore.h
index 95c8341eb..4c7695f16 100644
